        if len(panes)!=1:return None
        r=match(items(panes[0]))
        return r if len(r)==6 else None
    rows=until(getrows,"flyExplorer Known Folder rows not found")
    time.sleep(1)
    print("FLY_KNOWN_FOLDER_COUNT",len(rows),flush=True)
    for key in targets:
        item,name=rows[key]
        imgs=[x for x in item.descendants() if x.element_info.control_type=="Image" and x.element_info.name=="Windows Known Folder artwork"]
        rr=item.rectangle(); ir=imgs[0].rectangle() if imgs else None
        print("FLY_KNOWN_FOLDER_ROW",key,repr(name),rr.left,rr.top,rr.width(),rr.height(),"ARTWORK_IMAGES",len(imgs),"IMAGE_RECT",None if ir is None else (ir.left,ir.top,ir.width(),ir.height()),flush=True)
        if len(imgs)!=1:raise AssertionError(key+" artwork image count="+str(len(imgs)))
    print("FLY_SCREENSHOT_BEGIN",flush=True);print(shot(aw),flush=True);print("FLY_SCREENSHOT_END",flush=True)
finally:
